import{_ as i,c as t,o as a,ae as s}from"./chunks/framework.DMK_uHmU.js";const g=JSON.parse('{"title":"User Activities and Analytics Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/Manage/Users/user-activities.md","filePath":"Administration/Manage/Users/user-activities.md"}'),o={name:"Administration/Manage/Users/user-activities.md"};function n(r,e,l,c,u,d){return a(),t("div",null,e[0]||(e[0]=[s('<h1 id="user-activities-and-analytics-guide" tabindex="-1">User Activities and Analytics Guide <a class="header-anchor" href="#user-activities-and-analytics-guide" aria-label="Permalink to &quot;User Activities and Analytics Guide&quot;">​</a></h1><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#user-activities-and-analytics-guide">User Activities and Analytics Guide</a><ul><li><a href="#table-of-contents">Table of Contents</a></li><li><a href="#introduction">Introduction</a></li><li><a href="#accessing-user-activities">Accessing User Activities</a></li><li><a href="#activities-interface-overview">Activities Interface Overview</a></li><li><a href="#token-usage-analytics">Token Usage Analytics</a><ul><li><a href="#key-metrics-displayed">Key Metrics Displayed</a></li><li><a href="#token-usage-chart">Token Usage Chart</a></li><li><a href="#features">Features</a></li></ul></li><li><a href="#login-history">Login History</a><ul><li><a href="#login-activity-chart">Login Activity Chart</a></li><li><a href="#features-1">Features</a></li><li><a href="#login-statistics">Login Statistics</a></li></ul></li><li><a href="#device-tracking">Device Tracking</a><ul><li><a href="#device-table">Device Table</a></li><li><a href="#ip-geolocation">IP Geolocation</a></li><li><a href="#security-features">Security Features</a></li></ul></li><li><a href="#user-metadata">User Metadata</a><ul><li><a href="#account-metadata">Account Metadata</a></li></ul></li><li><a href="#data-visualization-features">Data Visualization Features</a></li><li><a href="#security-monitoring">Security Monitoring</a></li><li><a href="#troubleshooting">Troubleshooting</a></li></ul></li></ul><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The User Activities component provides comprehensive analytics and tracking information about a user&#39;s system interactions, including AI token usage, login history, device access, and metadata. This tool allows administrators to monitor usage patterns, identify security concerns, and analyze how users are interacting with the platform.</p><h2 id="accessing-user-activities" tabindex="-1">Accessing User Activities <a class="header-anchor" href="#accessing-user-activities" aria-label="Permalink to &quot;Accessing User Activities&quot;">​</a></h2><p>The User Activities component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access this component:</p><ol><li>Navigate to a user profile page (<code>/user/profile/[user_id]</code>)</li><li>Click on the &quot;Activities&quot; tab in the left navigation menu</li></ol><h2 id="activities-interface-overview" tabindex="-1">Activities Interface Overview <a class="header-anchor" href="#activities-interface-overview" aria-label="Permalink to &quot;Activities Interface Overview&quot;">​</a></h2><p>The User Activities interface features a tabbed layout with four main sections:</p><ol><li><strong>Tokens</strong>: Displays AI token usage statistics and charts</li><li><strong>Logins</strong>: Shows login frequency and patterns over time</li><li><strong>Devices / Last seen</strong>: Lists devices used to access the system</li><li><strong>Meta</strong>: Shows system metadata about the user account</li></ol><p>Each tab contains specialized visualizations and data displays relevant to that category of user activity.</p><h2 id="token-usage-analytics" tabindex="-1">Token Usage Analytics <a class="header-anchor" href="#token-usage-analytics" aria-label="Permalink to &quot;Token Usage Analytics&quot;">​</a></h2><p>The Tokens tab provides detailed information about a user&#39;s AI token consumption:</p><h3 id="key-metrics-displayed" tabindex="-1">Key Metrics Displayed <a class="header-anchor" href="#key-metrics-displayed" aria-label="Permalink to &quot;Key Metrics Displayed&quot;">​</a></h3><ol><li><strong>Total Requests</strong>: The number of AI requests made by the user</li><li><strong>Total Tokens</strong>: Combined total of input and output tokens used</li><li><strong>Input Tokens</strong>: Number of tokens used for prompts sent to AI models</li><li><strong>Output Tokens</strong>: Number of tokens used for responses from AI models</li></ol><h3 id="token-usage-chart" tabindex="-1">Token Usage Chart <a class="header-anchor" href="#token-usage-chart" aria-label="Permalink to &quot;Token Usage Chart&quot;">​</a></h3><p>The interactive chart shows:</p><ul><li><strong>Input Tokens</strong>: Green bars representing daily input token usage</li><li><strong>Output Tokens</strong>: Blue bars representing daily output token usage</li><li><strong>User Requests</strong>: Orange line showing the number of AI requests made</li></ul><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>Time-based Analysis</strong>: View token usage patterns over time</li><li><strong>Automatic Scaling</strong>: Large numbers (thousands, millions) are automatically formatted (e.g., 5.2K, 1.3M)</li><li><strong>Tooltip Details</strong>: Hover over chart elements to see precise values</li><li><strong>Stacked Display</strong>: Input and output tokens are stacked to show total daily usage</li></ul><p>This visualization helps administrators monitor AI resource usage and identify unusual patterns or excessive consumption.</p><h2 id="login-history" tabindex="-1">Login History <a class="header-anchor" href="#login-history" aria-label="Permalink to &quot;Login History&quot;">​</a></h2><p>The Logins tab tracks when and how frequently a user has accessed the system:</p><h3 id="login-activity-chart" tabindex="-1">Login Activity Chart <a class="header-anchor" href="#login-activity-chart" aria-label="Permalink to &quot;Login Activity Chart&quot;">​</a></h3><p>The chart displays:</p><ul><li><strong>Login Frequency</strong>: Blue bars showing the number of logins per day</li><li><strong>Time Period</strong>: X-axis shows dates of login activity</li></ul><h3 id="features-1" tabindex="-1">Features <a class="header-anchor" href="#features-1" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li><strong>Login Trends</strong>: Identify patterns in system access (weekdays vs. weekends, working hours)</li><li><strong>Activity Gaps</strong>: Spot periods of inactivity</li><li><strong>High-Volume Access</strong>: Identify unusual login frequency that might indicate shared accounts or security issues</li></ul><h3 id="login-statistics" tabindex="-1">Login Statistics <a class="header-anchor" href="#login-statistics" aria-label="Permalink to &quot;Login Statistics&quot;">​</a></h3><ul><li><strong>Total Logins</strong>: Cumulative number of times the user has logged in</li><li><strong>Average Logins</strong>: Statistical average of login frequency over the displayed period</li></ul><h2 id="device-tracking" tabindex="-1">Device Tracking <a class="header-anchor" href="#device-tracking" aria-label="Permalink to &quot;Device Tracking&quot;">​</a></h2><p>The Devices / Last seen tab shows all devices used to authenticate with the system:</p><h3 id="device-table" tabindex="-1">Device Table <a class="header-anchor" href="#device-table" aria-label="Permalink to &quot;Device Table&quot;">​</a></h3><p>The table displays the following information for each device:</p><ul><li><strong>Device Browser</strong>: Browser and OS information</li><li><strong>Status</strong>: Visual indicator showing if the device is valid (green check) or invalid (red x)</li><li><strong>IP Address</strong>: The last IP address used for authentication</li><li><strong>Last Auth</strong>: Date and time of the most recent authentication</li></ul><h3 id="ip-geolocation" tabindex="-1">IP Geolocation <a class="header-anchor" href="#ip-geolocation" aria-label="Permalink to &quot;IP Geolocation&quot;">​</a></h3><p>When selecting a device row:</p><ol><li>A dialog opens showing the IP address location</li><li>A map is displayed pinpointing the geographical location</li><li>Additional information is shown: <ul><li>ISP (Internet Service Provider)</li><li>Country</li><li>Region</li><li>City</li><li>ZIP/Postal Code</li></ul></li></ol><h3 id="security-features" tabindex="-1">Security Features <a class="header-anchor" href="#security-features" aria-label="Permalink to &quot;Security Features&quot;">​</a></h3><ul><li>Quickly identify suspicious login locations</li><li>Track multiple devices used by a single user</li><li>Verify authentication from expected locations</li></ul><h2 id="user-metadata" tabindex="-1">User Metadata <a class="header-anchor" href="#user-metadata" aria-label="Permalink to &quot;User Metadata&quot;">​</a></h2><p>The Meta tab displays system information about the user account:</p><h3 id="account-metadata" tabindex="-1">Account Metadata <a class="header-anchor" href="#account-metadata" aria-label="Permalink to &quot;Account Metadata&quot;">​</a></h3><ul><li><strong>Creation Date</strong>: When the user account was created</li><li><strong>Last Modified</strong>: When the user profile was last updated</li><li><strong>Created By</strong>: Administrator who created the account</li><li><strong>Account Status History</strong>: Timeline of account status changes</li><li><strong>System Identifiers</strong>: Internal IDs and references</li></ul><p>This information provides administrative context about the user account&#39;s lifecycle.</p><h2 id="data-visualization-features" tabindex="-1">Data Visualization Features <a class="header-anchor" href="#data-visualization-features" aria-label="Permalink to &quot;Data Visualization Features&quot;">​</a></h2><p>The User Activities component uses several visualization techniques:</p><ol><li><strong>Bar Charts</strong>: For displaying discrete values over time (logins, token usage)</li><li><strong>Line Charts</strong>: For showing trends and continuous data</li><li><strong>Stacked Charts</strong>: For comparing related values (input vs. output tokens)</li><li><strong>Interactive Maps</strong>: For visualizing geographical data</li><li><strong>Data Tables</strong>: For presenting detailed information about devices</li></ol><p>Common features across visualizations:</p><ul><li>Responsive design that adapts to different screen sizes</li><li>Consistent color coding (green for input, blue for output, orange for requests)</li><li>Interactive tooltips showing precise values</li><li>Automatic data formatting for readability</li></ul><h2 id="security-monitoring" tabindex="-1">Security Monitoring <a class="header-anchor" href="#security-monitoring" aria-label="Permalink to &quot;Security Monitoring&quot;">​</a></h2><p>The User Activities component serves an important security function:</p><ol><li><p><strong>Unusual Activity Detection</strong>:</p><ul><li>Spikes in token usage</li><li>Logins from new locations</li><li>Multiple devices in different geographic regions</li><li>Logins outside normal working hours</li></ul></li><li><p><strong>Account Compromise Indicators</strong>:</p><ul><li>Sudden changes in usage patterns</li><li>Authentication from unexpected countries</li><li>Multiple failed login attempts</li><li>Unusual token consumption patterns</li></ul></li><li><p><strong>Resource Abuse Monitoring</strong>:</p><ul><li>Excessive token usage</li><li>API request frequency beyond normal patterns</li><li>Multiple concurrent sessions</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Token usage data not loading</p><ul><li>Check if the user has made any AI requests</li><li>Verify that the user ID is correct</li><li>Ensure you have permission to view analytics data</li></ul><p><strong>Issue</strong>: Login chart shows no data</p><ul><li>The user may not have logged in during the selected period</li><li>Check if there are authentication records for this user</li><li>Verify the account has been activated</li></ul><p><strong>Issue</strong>: Device information is missing</p><ul><li>The user may not have completed any successful logins</li><li>Device tracking may be disabled in system settings</li><li>Check browser cookie settings for the user&#39;s browsers</li></ul><p><strong>Issue</strong>: Geolocation not working</p><ul><li>Network issues may prevent IP lookup</li><li>VPN usage may obscure actual location</li><li>IP address may be internal or not publicly routable</li></ul><p><strong>Issue</strong>: &quot;Services Error&quot; message</p><ul><li>Note the error code provided in the message</li><li>Check network connectivity</li><li>Contact system administrator if the issue persists</li></ul><hr><p>For additional information on user activity monitoring and analytics interpretation, please refer to the System Administration Guide.</p>',69)]))}const p=i(o,[["render",n]]);export{g as __pageData,p as default};
